query:
UPDATE users SET waitlistStatus = 'pending' WHERE waitlistStatus IS NULL OR waitlistStatus = '';
UPDATE users SET referralCode = LOWER(SUBSTRING(MD5(CONCAT(id, RAND())), 1, 12)) WHERE referralCode IS NULL;
UPDATE users u JOIN (SELECT id, ROW_NUMBER() OVER (ORDER BY created_at ASC) AS pos FROM users) ranked ON u.id = ranked.id SET u.waitlistPosition = ranked.pos WHERE u.waitlistPosition IS NULL;
UPDATE users SET waitlistJoinedAt = created_at WHERE waitlistJoinedAt IS NULL;

